<script setup>
import { onMounted, ref } from 'vue'
import SidebarMenu from '../components/SidebarMenu.vue'
import { getAbsences, modifierStatutAbsence } from '../services/absence'

const absences = ref([]); const loading = ref(false); const error = ref(''); const message = ref(''); const menuOuvert = ref(false); const absenceSelectionnee = ref(null); const formulaire = ref({ statut: '', motif: '' })
async function charger() { loading.value = true; try { absences.value = (await getAbsences()).absences || [] } catch (e) { error.value = e.message } finally { loading.value = false } }
function ouvrirModification(absence) { absenceSelectionnee.value = absence; formulaire.value = { statut: absence.statut, motif: absence.motif || '' }; error.value = ''; message.value = '' }
async function enregistrerModification() { if (!absenceSelectionnee.value) return; try { await modifierStatutAbsence(absenceSelectionnee.value.id, formulaire.value.statut, formulaire.value.motif); message.value = 'Absence mise à jour.'; absenceSelectionnee.value = null; await charger() } catch (e) { error.value = e.message } }
onMounted(charger)
</script>
<template><div class="app-layout"><SidebarMenu nom="Ressources humaines" role="RH" code-role="RH" initiales="RH" :ouvert="menuOuvert" @fermer="menuOuvert = false" /><main class="page"><button class="burger" @click="menuOuvert = true">☰ Menu</button><div class="contenu"><p class="eyebrow">Ressources humaines</p><h1>Gestion des absences</h1><p class="subtitle">Les absences sont détectées automatiquement à partir du planning. Cliquez sur une ligne pour la modifier.</p><p v-if="error" class="alert error">{{ error }}</p><p v-if="message" class="alert success">{{ message }}</p><section v-if="absenceSelectionnee" class="card"><h2>Modifier l’absence</h2><form @submit.prevent="enregistrerModification"><label>Employé<input :value="absenceSelectionnee.nom_complet || absenceSelectionnee.matricule" disabled /></label><label>Date<input :value="absenceSelectionnee.date" disabled /></label><label>Statut<select v-model="formulaire.statut"><option value="A_TRAITER">À traiter</option><option value="JUSTIFIEE_AUTORISEE">Justifiée et autorisée</option><option value="NON_JUSTIFIEE">Non justifiée</option></select></label><label>Motif<textarea v-model="formulaire.motif" rows="3" required /></label><div class="actions"><button class="cancel" type="button" @click="absenceSelectionnee = null">Annuler</button><button class="button" type="submit">Enregistrer</button></div></form></section><section class="card"><p v-if="loading" class="empty">Chargement...</p><p v-else-if="!absences.length" class="empty">Aucune absence détectée.</p><div v-else class="table-wrap"><table><thead><tr><th>Employé</th><th>Date</th><th>Motif</th><th>Statut</th><th>Retenue</th></tr></thead><tbody><tr v-for="a in absences" :key="a.id" class="ligne" @click="ouvrirModification(a)"><td>{{ a.nom_complet || a.matricule }}</td><td>{{ a.date }}</td><td>{{ a.motif }}</td><td>{{ a.statut }}</td><td class="retenue">{{ Number(a.retenue).toFixed(2) }}</td></tr></tbody></table></div></section></div></main></div></template>
<style scoped>.app-layout{display:grid;grid-template-columns:260px minmax(0,1fr);min-height:100vh;background:#f1f3f6;color:#222;font-family:Inter,system-ui,sans-serif}.page{min-width:0}.burger{display:none;margin:16px;padding:8px 16px;border:0;border-radius:10px;background:#fff;color:teal;font-weight:700}.contenu{max-width:1100px;margin:auto;padding:40px 20px}.eyebrow{color:#667085;font-size:12px;font-weight:700;text-transform:uppercase}h1{margin:0;color:teal}.subtitle{color:#667085}.card{margin-top:22px;padding:22px;background:#fff;border-radius:10px;box-shadow:0 3px 12px #0002}form{display:grid;gap:12px;max-width:600px}label{display:grid;gap:6px;font-weight:700;font-size:13px}input,select,textarea{padding:10px;border:1px solid #c8ced8;border-radius:7px;font:inherit}.actions{display:flex;gap:10px}.button,.cancel{padding:10px 16px;border:0;border-radius:20px;background:teal;color:#fff;font-weight:700;cursor:pointer}.cancel{background:#eef2f4;color:#344054}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:12px 8px;border-bottom:1px solid #e5e7eb;text-align:left;white-space:nowrap}th{color:#667085;text-transform:uppercase;font-size:11px}.ligne{cursor:pointer}.ligne:hover{background:#eef7f7}.retenue{color:#b42318;font-weight:700}.empty{color:#667085}.alert{padding:12px;border-radius:8px}.error{background:#fee;color:#b42318}.success{background:#e8f5e9;color:#137333}@media(max-width:960px){.app-layout{grid-template-columns:1fr}.burger{display:block}}</style>
